from pwn import *

def create_cyclic_pattern(size):
    return cyclic(size)

def main():
    server = ('pwn.chal.csaw.io', 28201)

    retries = 3  # Retry count if EOFError occurs
    pattern_size = [512, 768]  # Different size patterns to test

    for size in pattern_size:
        pattern = create_cyclic_pattern(size)
        attempt = 0

        while attempt < retries:
            try:
                log.info(f"Sending pattern of size {size}, attempt {attempt + 1}")
                conn = remote(server[0], server[1])
                conn.sendline(pattern)

                # Attempt to receive all server responses until connection closes
                response = conn.recvall(timeout=5)
                log.info(f"Received from server after sending {size}: {response}")
                conn.close()

                break  # Exit retry loop on success

            except EOFError:
                log.warning(f"EOFError occurred, retrying... (attempt {attempt + 1})")
                attempt += 1
                conn.close() if 'conn' in locals() else None

        if attempt == retries:
            log.error(f"Failed to communicate with the server using pattern size {size} after retries.")

if __name__ == "__main__":
    main()

